package crdt

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// fixtureDir holds the JSON generated by scripts/gen-crdt-fixtures.mjs from
// the JS reference implementation.
const fixtureDir = "../../testdata/crdt"

func loadFixture(t *testing.T, name string, dst any) {
	t.Helper()

	raw, err := os.ReadFile(filepath.Join(fixtureDir, name))
	if err != nil {
		t.Fatalf("read fixture %s: %v (run `make fixtures`)", name, err)
	}
	if err := json.Unmarshal(raw, dst); err != nil {
		t.Fatalf("decode fixture %s: %v", name, err)
	}
}

type murmurFixture struct {
	Cases []struct {
		Input string `json:"input"`
		Hash  uint32 `json:"hash"`
	} `json:"cases"`
}

func TestMurmur3Golden(t *testing.T) {
	var fixture murmurFixture
	loadFixture(t, "murmur.json", &fixture)

	if len(fixture.Cases) < 200 {
		t.Fatalf("fixture has %d cases, want at least 200", len(fixture.Cases))
	}

	for _, testCase := range fixture.Cases {
		if got := Murmur3String(testCase.Input); got != testCase.Hash {
			t.Errorf("Murmur3String(%q) = %d, want %d", testCase.Input, got, testCase.Hash)
		}
	}
}

type timestampCase struct {
	Input  string `json:"input"`
	OK     bool   `json:"ok"`
	Millis int64  `json:"millis"`
	Str    string `json:"str"`
	// Hash is the unsigned murmur3 value; Timestamp.Hash() narrows it to the
	// signed int32 the merkle trie stores (JS `^` does the same).
	Hash uint32 `json:"hash"`
}

type timestampFixture struct {
	Cases []timestampCase `json:"cases"`
}

func TestTimestampGolden(t *testing.T) {
	var fixture timestampFixture
	loadFixture(t, "timestamps.json", &fixture)

	if len(fixture.Cases) < 200 {
		t.Fatalf("fixture has %d cases, want at least 200", len(fixture.Cases))
	}

	valid := 0
	for _, testCase := range fixture.Cases {
		timestamp, ok := Parse(testCase.Input)

		if ok != testCase.OK {
			t.Errorf("Parse(%q) ok = %v, want %v", testCase.Input, ok, testCase.OK)
			continue
		}
		if !ok {
			continue
		}
		valid++

		if got := timestamp.Millis(); got != testCase.Millis {
			t.Errorf("Parse(%q).Millis() = %d, want %d", testCase.Input, got, testCase.Millis)
		}
		if got := timestamp.String(); got != testCase.Str {
			t.Errorf("Parse(%q).String() = %q, want %q", testCase.Input, got, testCase.Str)
		}
		if got, want := timestamp.Hash(), int32(testCase.Hash); got != want {
			t.Errorf("Parse(%q).Hash() = %d, want %d", testCase.Input, got, want)
		}

		// String() output must parse back to the same value.
		roundTripped, ok := Parse(testCase.Str)
		if !ok {
			t.Errorf("Parse(%q).String() did not round-trip", testCase.Input)
			continue
		}
		if roundTripped.Hash() != timestamp.Hash() {
			t.Errorf("Parse(%q) does not round-trip its hash", testCase.Input)
		}
	}

	if valid < 150 {
		t.Errorf("only %d valid timestamp fixtures, want at least 150", valid)
	}
}

func TestTimestampStringReformats(t *testing.T) {
	// Short counter and node are padded, so the output differs from the input.
	timestamp, ok := Parse("2020-01-01T00:00:00.000Z-0-0")
	if !ok {
		t.Fatal("Parse failed")
	}
	if got, want := timestamp.String(), "2020-01-01T00:00:00.000Z-0000-0000000000000000"; got != want {
		t.Errorf("String() = %q, want %q", got, want)
	}
}

func TestTimestampHashIsSignedInt32(t *testing.T) {
	timestamp, ok := Parse("1970-01-01T00:00:00.000Z-0000-0000000000000000")
	if !ok {
		t.Fatal("Parse failed")
	}

	unsigned := Murmur3String(timestamp.String())
	if got, want := timestamp.Hash(), int32(unsigned); got != want {
		t.Errorf("Hash() = %d, want int32(%d)", got, unsigned)
	}
}

func TestTimestampErrors(t *testing.T) {
	for _, input := range []string{
		"",
		"invalid",
		"2020-01-01T00:00:00.000Z",
		"2020-01-01T00:00:00.000Z-10000-0123456789ABCDEF",
		"2020-01-01T00:00:00.000Z-0000-0123456789ABCDEFG",
		"1969-12-31T23:59:59.999Z-0000-0123456789ABCDEF",
	} {
		if _, ok := Parse(input); ok {
			t.Errorf("Parse(%q) = ok, want invalid", input)
		}
	}
}
